#!/usr/bin/env node
'use strict';
// Makes the "English-only Snowball" patch for releases whose snowball directory is built the old way (up to 15: the
// text search SQL is generated by a shell loop over LANGUAGES in the Makefile; 16 and later use snowball_create.pl, see
// patches/common/0004). The patch itself is data in patches/common/<range>/; this tool only writes it, by applying the
// same edit to the release's files and diffing.
//
//   make-snowball-patch.js --to 15.19 --range pg15        (tools container)
//
// The edit: Makefile keeps only the UTF-8 English stemmer object and the english language entry; dict_snowball.c keeps
// only the UTF-8 English stemmer (header and STEMMER_MODULE entry).
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const root = path.resolve(__dirname, '..');
const arg = (k) => { const i = process.argv.indexOf(`--${k}`); return i > 0 ? process.argv[i + 1] : undefined; };
const to = arg('to'); const range = arg('range');
if (!to || !range) { console.error('usage: make-snowball-patch.js --to <version> --range <name>'); process.exit(2); }
const dir = path.join(root, 'cache', 'src', to, 'src', 'backend', 'snowball');
const files = { Makefile: path.join(dir, 'Makefile'), 'dict_snowball.c': path.join(dir, 'dict_snowball.c') };

function editMakefile(t) {
  // the stemmer object list
  const objs = /^OBJS \+= \\\n(?:\tstem_[A-Za-z0-9_]+\.o(?: \\)?\n)+/m;
  // older releases (12 and before) list the stemmers right after the common objects in the OBJS= line
  const objsOld = /^(OBJS=.*utilities\.o) \\\n(?:\tstem_[A-Za-z0-9_]+\.o(?: \\)?\n)+/m;
  if (objs.test(t)) t = t.replace(objs, 'OBJS += \\\n\tstem_UTF_8_english.o\n');
  else if (objsOld.test(t)) t = t.replace(objsOld, '$1 stem_UTF_8_english.o\n');
  else throw new Error('Makefile: stemmer object list not found');
  // the language list: language and the dictionary used for all-ASCII words
  const langs = /^LANGUAGES=\s*\\\n(?:\t[a-z]+[ \t]+[a-z]+[ \t]*(?:\\)?\n)+/m;
  if (!langs.test(t)) throw new Error('Makefile: LANGUAGES list not found');
  return t.replace(langs, 'LANGUAGES=  \\\n\tenglish\t\tenglish\n');
}

function editDict(t) {
  t = t.replace(/^#include "snowball\/libstemmer\/stem_(?!UTF_8_english\.h)[A-Za-z0-9_]+\.h"\n/gm, '');
  if (!t.includes('stem_UTF_8_english.h')) {
    t = t.replace('#include "snowball/libstemmer/header.h"\n', '#include "snowball/libstemmer/header.h"\n#include "snowball/libstemmer/stem_UTF_8_english.h"\n');
  }
  const marker = '\t * Stemmers list from Snowball distribution\n\t */\n';
  if (!t.includes(marker)) throw new Error('dict_snowball.c: stemmer list comment not found');
  const before = t;
  // 12 and later use the STEMMER_MODULE macro; older releases spell every entry out as a struct initializer
  t = t.replace(/^\tSTEMMER_MODULE\([^\n]*\),\n/gm, '');
  if (t !== before) return t.replace(marker, `${marker}\tSTEMMER_MODULE(english, PG_UTF8, UTF_8),\n`);
  t = t.replace(/^\t\{"[a-z]+", PG_[A-Z0-9_]+, [a-z]+_[A-Za-z0-9_]+_create_env, [^\n]*\},\n/gm, '');
  if (t === before) throw new Error('dict_snowball.c: stemmer entries not found');
  return t.replace(marker, `${marker}\t{"english", PG_UTF8, english_UTF_8_create_env, english_UTF_8_close_env, english_UTF_8_stem},\n`);
}

const edits = { Makefile: editMakefile, 'dict_snowball.c': editDict };
const tmp = fs.mkdtempSync('/tmp/snowball-');
let body = '';
for (const [name, file] of Object.entries(files)) {
  const rel = `src/backend/snowball/${name}`;
  const orig = fs.readFileSync(file, 'utf8');
  const next = edits[name](orig);
  const o = path.join(tmp, 'o'); const n = path.join(tmp, 'n');
  fs.writeFileSync(o, orig); fs.writeFileSync(n, next);
  const d = spawnSync('diff', ['-u', '--label', `a/${rel}`, '--label', `b/${rel}`, o, n], { encoding: 'utf8' });
  body += `diff --git a/${rel} b/${rel}\n${d.stdout}`;
}
const header = `Subject: Keep only the English Snowball stemmer
Purpose: The standard build links stemmers for about 28 languages and creates a text search configuration for each at initdb. The profile needs text search to work, not 28 languages, so only the English UTF-8 stemmer and its configuration are kept (the Makefile of this release generates the configurations from its LANGUAGES list, so the list is cut to english). Other text search configurations are not created; to_tsvector with 'english' and 'simple' work as before. Same effect as common/0004 for 16 and later, made for the older way this directory is built.
Components: src/backend/snowball/dict_snowball.c, src/backend/snowball/Makefile
Checks: scripts/native-image.sh test (to_tsvector english stems foxes to fox; pg_ts_config lists exactly english and simple)
Origin: own

`;
const dest = path.join(root, 'patches', 'common', range, '0004-snowball-english-only.patch');
fs.mkdirSync(path.dirname(dest), { recursive: true });
fs.writeFileSync(dest, header + body);
fs.rmSync(tmp, { recursive: true, force: true });
console.log(`wrote ${path.relative(root, dest)}`);
